/* @capture workbench.css@2 */
.monaco-editor {
  position: relative;
  overflow: visible;
  text-size-adjust: 100%;
  text-spacing-trim: space-all;
  color: var(--vscode-editor-foreground);
  background-color: var(--vscode-editor-background);
  overflow-wrap: initial;
}

