}

/* @capture workbench.css@10 */
.monaco-editor .view-overlays {
  position: absolute;
  top: 0px;
}

/* @capture workbench.css@11 */
.monaco-editor .view-overlays > :is(div, vsc-notification-toasts, vsc-chat-markdown, vsc-chat-question-carousel, vsc-chat-question-option, vsc-chat-question-summary, vsc-chat-request, vsc-chat-response, vsc-chat-tool-call, vsc-chat-tool-chain, vsc-notification, vsc-checkbox, vsc-toggle, vsc-view-tabs),
.monaco-editor .margin-view-overlays > :is(div, vsc-notification-toasts, vsc-chat-markdown, vsc-chat-question-carousel, vsc-chat-question-option, vsc-chat-question-summary, vsc-chat-request, vsc-chat-response, vsc-chat-tool-call, vsc-chat-tool-chain, vsc-notification, vsc-checkbox, vsc-toggle, vsc-view-tabs) {
  position: absolute;
  width: 100%;
}

/* @capture workbench.css@22 */
.monaco-scrollable-element > .visible {
  opacity: 1;
  background: rgba(0, 0, 0, 0);
  transition: opacity 0.1s linear;
  z-index: 11;
}

/* @capture workbench.css@23 */
.monaco-scrollable-element > .invisible {
  opacity: 0;
  pointer-events: none;
}

/* @capture workbench.css@24 */
.monaco-scrollable-element > .invisible.fade {
  transition: opacity 0.8s linear;
}

/* @capture workbench.css@26 */
.monaco-scrollable-element > .shadow {
  position: absolute;
  display: none;
}

/* @capture workbench.css@27 */
.monaco-scrollable-element > .shadow.top {
