/* ---- vsc-workbench (workbench) ---- */

/*
 * Agents window root variables (window="agents"). Element captures don't include these because they are set on
 * the workbench itself. Copied from src/vs/workbench/contrib/modernUI/browser/media/frostedGlass.css (frosted
 * menus: the action widget is transparent and its ::before blurs a translucent menu color) and
 * src/vs/sessions/browser/media/style.css (Agents pickers use the agents panel color as their solid menu color).
 */
@supports (backdrop-filter: blur(12px)) and (background-color: color-mix(in srgb, black 92%, transparent)) {
  @media (prefers-reduced-transparency: no-preference) and (forced-colors: none) {
    .monaco-workbench.modern-ui-frosted-glass:not(.hc-black):not(.hc-light) {
      --modern-ui-glass-quick-input-background: color-mix(in srgb, var(--modern-ui-solid-quick-input-background) var(--modern-ui-glass-opacity, 92%), transparent);
      --modern-ui-glass-menu-background: color-mix(in srgb, var(--modern-ui-solid-menu-background) var(--modern-ui-glass-opacity, 92%), transparent);
      --modern-ui-glass-hover-background: color-mix(in srgb, var(--vscode-editorHoverWidget-background) var(--modern-ui-glass-opacity, 92%), transparent);
      --modern-ui-glass-dialog-background: color-mix(in srgb, var(--modern-ui-solid-dialog-background) var(--modern-ui-glass-opacity, 92%), transparent);
      --modern-ui-glass-notifications-background: color-mix(in srgb, var(--vscode-notifications-background) var(--modern-ui-glass-opacity, 92%), transparent);
      --modern-ui-solid-dialog-background: var(--vscode-editorWidget-background);
      --modern-ui-solid-menu-background: var(--vscode-menu-background);
      --modern-ui-solid-quick-input-background: var(--vscode-quickInput-background);
    }

    .monaco-workbench.agent-sessions-workbench.modern-ui-frosted-glass:not(.hc-black):not(.hc-light) {
      --modern-ui-solid-menu-background: var(--vscode-agentsPanel-background);
      --modern-ui-solid-quick-input-background: var(--vscode-agentsPanel-background);
    }

    .monaco-workbench.modern-ui-frosted-glass:not(.hc-black):not(.hc-light).monaco-enable-motion .action-widget.action-widget-animated:not(.action-widget-dropdown-closing) {
      animation: action-widget-scale-open 250ms cubic-bezier(0.22, 1, 0.36, 1) backwards;
      transform-origin: bottom left;
    }

    .monaco-workbench.modern-ui-frosted-glass:not(.hc-black):not(.hc-light).monaco-enable-motion .context-view.bottom .action-widget.action-widget-animated {
      transform-origin: top left;
    }
  }
}

/* From src/vs/platform/actionWidget/browser/actionWidget.css (the keyframes aren't part of an element capture). */
@keyframes action-widget-scale-open {
  from {
    transform: scale(0.97);
  }
  to {
    transform: scale(1);
  }
}

/* ---- vsc-chat-mode-picker (chat-mode-picker) ---- */

/*
 * Responsive state (compact-picker) from
 * src/vs/workbench/contrib/chat/browser/agentSessions/agentHost/media/agentHostModePicker.css: the mode's icon only,
 * without the permissions half. Copied from source because the state wasn't captured; the label and sizing rules it
 * shares with other session pickers are in <vsc-session-picker>'s component.css.
 */
.compact-picker .agent-host-mode-permission-summary,
.compact-picker .agent-host-mode-sandbox-icon {
  display: none;
}

.compact-picker .agent-host-mode-permissions-trigger .agent-host-permissions-button {
  display: none;
}

.compact-picker .agent-host-mode-permissions-trigger .agent-host-mode-button {
  width: var(--chat-input-control-height);
  padding: 0;
  justify-content: center;
}

/* ---- vsc-chat-model-picker (chat-model-picker) ---- */

/*
 * Responsive states (ChatInputPickerResponsiveLayout) from
 * src/vs/workbench/contrib/chat/browser/widget/input/modelPicker/media/modelPicker.css. They weren't on screen when the
 * picker was captured, so the rules are copied from source. Compact (icon + configuration summary) and minimal (icon
 * only) drop the model name: the product stops rendering it, here the last rule hides it.
 */
.interactive-session .chat-input-toolbar .chat-input-picker-item .action-label.model-picker-split.icon-only .model-picker-section {
  width: 100%;
  height: 100%;
  padding: 0;
  justify-content: center;
}

.interactive-session .chat-input-toolbar .chat-input-picker-item.compact-picker .action-label.model-picker-split.compact {
  justify-content: flex-start;
}

.chat-input-picker-item .action-label.model-picker-split.compact .model-picker-name {
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  padding: 0;
  justify-content: center;
}

.chat-input-picker-item .action-label.model-picker-split.compact .model-picker-name > .codicon {
  width: var(--vscode-codiconFontSize-compact);
  height: var(--vscode-codiconFontSize-compact);
  line-height: var(--vscode-codiconFontSize-compact);
}

.interactive-session .chat-input-toolbar .chat-input-picker-item .action-label.model-picker-split.icon-only.minimal .model-picker-name {
  width: 22px;
  height: 22px;
  padding: 0;
  justify-content: center;
}

.chat-input-picker-item .action-label.model-picker-split.compact .model-picker-name > :not(.codicon) {
  display: none;
}

