  margin: 0;
  padding-block: 0;
  line-height: 20px;
}

/* ---- vsc-view-tab (view-tab) ---- */

/* Authored: plain-text count after a tab label (not part of the captured panel; VS Code panel tabs use a hidden activity badge instead). */
vsc-view-tab .action-label .view-tab-count {
  margin-left: 6px;
  font-size: var(--vscode-agents-fontSize-label2, 11px);
  color: var(--vscode-descriptionForeground);
  font-weight: var(--vscode-fontWeight-regular);
}

/* Authored: the focus ring shows for keyboard focus only (:focus-visible), never while a tab is pressed or after a click.
   (The product approximates this with a "clicked" class set on mousedown.) */
/* The tab's own ring is on .active-item-indicator; drop the workbench's generic [tabindex]:focus outline on the host. */
.monaco-workbench vsc-view-tab.action-item:focus {
  outline: none;
}

.monaco-workbench vsc-view-tab.action-item:focus:not(:focus-visible) > .active-item-indicator {
  outline: none !important;
}

/* ---- vsc-chat-input (chat-input) ---- */

/*
 * Editor stand-in for the chat input's Monaco editor (ChatInputPart): font 13px, line height
 * 20px, 12px vertical padding, max height 250px, a 7px vertical scrollbar, laid out 6px wider
 * than its container (getLayoutData()). Placeholder styling mirrors
 * src/vs/editor/contrib/placeholderText/browser/placeholderText.css and the chat-session-detail
 * decoration (inputPlaceholderForeground).
 */
.interactive-input-editor .monaco-editor.dt-editor {
  position: relative;
  width: calc(100% + 6px);
  background-color: var(--vscode-input-background);
  color: var(--vscode-editor-foreground);
}

.dt-editor .dt-editor-text {
  box-sizing: border-box;
  min-height: 44px;
  max-height: 250px;
  overflow-y: auto;
  scrollbar-gutter: stable;
  padding: 12px 0;
  font-size: 13px;
  line-height: 20px;
  letter-spacing: 0px;
  font-feature-settings: "liga" 0, "calt" 0;
  font-variation-settings: normal;
  white-space: pre-wrap;
  overflow-wrap: break-word;
  outline: none;
  cursor: text;
  user-select: text;
  -webkit-user-select: text;
  caret-color: var(--vscode-editorCursor-foreground);
}

.dt-editor .dt-editor-text::selection {
  background-color: var(--vscode-editor-selectionBackground);
}

.dt-editor .dt-editor-text::-webkit-scrollbar {
  width: 7px;
}

.dt-editor .dt-editor-text::-webkit-scrollbar-thumb {
  background-color: transparent;
}

.dt-editor:hover .dt-editor-text::-webkit-scrollbar-thumb {
  background-color: var(--vscode-scrollbarSlider-background);
}

.dt-editor .dt-editor-text::-webkit-scrollbar-thumb:hover {
  background-color: var(--vscode-scrollbarSlider-hoverBackground);
}

.dt-editor .dt-editor-text::-webkit-scrollbar-thumb:active {
  background-color: var(--vscode-scrollbarSlider-activeBackground);
}

.dt-editor .editorPlaceholder {
  position: absolute;
  top: 12px;
  left: 0px;
  width: calc(100% - 7px);
  overflow: hidden;
  text-overflow: ellipsis;
  text-wrap: nowrap;
  pointer-events: none;
  font-size: 13px;
  line-height: 20px;
  color: var(--vscode-input-placeholderForeground);
}
